import { tv } from "tailwind-variants";

const checkbox = tv({
  slots: {
    root: [
      "flex size-4 shrink-0 items-center justify-center rounded-sm border border-input bg-background transition-all duration-150 ease-default outline-none",
      "focus-visible:ring-2 focus-visible:ring-ring/50",
      "data-checked:bg-primary data-checked:text-primary-foreground",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "data-invalid:border-destructive/50",
      "focus-visible:data-invalid:ring-destructive/50",
      "dark:bg-input/15",
      "dark:data-checked:bg-primary dark:data-checked:text-primary-foreground",
    ],
    indicator: [
      "flex items-center justify-center transition-[scale,opacity] duration-300 ease-default",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
      "data-unchecked:hidden",
      "[&>svg]:size-3 [&>svg]:shrink-0",
    ],
  },
});

export { checkbox };

"use client";

import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import { CheckIcon, MinusIcon } from "lucide-react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { checkbox } from "./checkbox.style";

function Checkbox({ className, ...props }: BaseCheckbox.Root.Props) {
  return (
    <BaseCheckbox.Root
      data-slot="checkbox"
      className={mergeSlotClassName(checkbox().root, className)}
      {...props}
    />
  );
}

function CheckboxIndicator({
  className,
  render,
  ...props
}: BaseCheckbox.Indicator.Props) {
  return (
    <BaseCheckbox.Indicator
      data-slot="checkbox-indicator"
      className={mergeSlotClassName(checkbox().indicator, className)}
      render={
        render !== undefined
          ? render
          : (indicatorProps, state) => (
              <span {...indicatorProps}>
                {state.indeterminate ? <MinusIcon /> : <CheckIcon />}
              </span>
            )
      }
      {...props}
    />
  );
}

export { Checkbox, CheckboxIndicator };
